236	    /**
237	     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
238	     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
239	     */
240	    @PrePersist
241	    void onCreate() {
242	        this.registrationDate = resolveRegistrationDate(this.registrationDate);
243	    }
244	
245	    /**
246	     * Resolves the effective registration date and rolls it onto a business day. An absent
247	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
248	     * The resulting date is then rolled forward so it never falls on a weekend: a Saturday or Sunday
249	     * becomes the following Monday, while any weekday is returned unchanged.
250	     *
251	     * <p>This is the single definition of both the defaulting and the business-day roll, used
252	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
253	     * stamps the owner and by the create endpoint that counts owners per business day.
254	     *
255	     * @param supplied the registration date from the request, or {@code null} when none was supplied
256	     * @return the effective registration date, guaranteed to fall on a business day
257	     */
258	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
259	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
260	        return switch (effective.getDayOfWeek()) {
261	            case SATURDAY -> effective.plusDays(2);
262	            case SUNDAY -> effective.plusDays(1);
263	            default -> effective;
264	        };
265	    }
266	
267	    protected Set<Pet> getPetsInternal() {
268	        if (this.pets == null) {
269	            this.pets = new HashSet<>();
270	        }
271	        return this.pets;
272	    }
273	
274	    protected void setPetsInternal(Set<Pet> pets) {
275	        this.pets = pets;
276	    }
277	
278	    public List<Pet> getPets() {
279	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
280	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
281	        return Collections.unmodifiableList(sortedPets);
282	    }
283	
284	    public void setPets(List<Pet> pets) {
285	        this.pets = new HashSet<>(pets);
286	    }
287	
288	    public void addPet(Pet pet) {
289	        getPetsInternal().add(pet);
290	        pet.setOwner(this);
291	    }
292	
293	    /**
294	     * Return the Pet with the given name, or null if none found for this Owner.
295	     *
296	     * @param name to test
297	     * @return true if pet name is already in use
298	     */
299	    public Pet getPet(String name) {
300	        return getPet(name, false);
301	    }
302	
303	    /**
304	     * Return the Pet with the given name, or null if none found for this Owner.
305	     *
306	     * @param name to test
307	     * @return true if pet name is already in use
308	     */
309	    public Pet getPet(String name, boolean ignoreNew) {
310	        name = name.toLowerCase();
311	        for (Pet pet : getPetsInternal()) {
312	            if (!ignoreNew || !pet.isNew()) {
313	                String compName = pet.getName();
314	                compName = compName.toLowerCase();
315	                if (compName.equals(name)) {
316	                    return pet;
317	                }
318	            }
319	        }
320	        return null;
321	    }
322	
323	    public Pet getPet(Integer petId) {
324	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
325	    }
326	
327	    @Override
328	    public String toString() {
329	        return new ToStringCreator(this)
330	
331	            .append("id", this.getId())
332	            .append("new", this.isNew())
333	            .append("lastName", this.getLastName())
334	            .append("firstName", this.getFirstName())
335	            .append("address", this.address)
336	            .append("city", this.city)
337	            .append("telephone", this.telephone)
338	            .toString();
339	    }
340	}
